-- Isolated MariaDB on 13316 only. Never import into a customer database.
CREATE TABLE companies (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,role ENUM('superadmin','admin','coach','player') NOT NULL,email VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,phone VARCHAR(50),current_credit DECIMAL(10,2) DEFAULT 0,notify_emails TINYINT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,name VARCHAR(255),default_slot_duration INT DEFAULT 30,min_booking_slots INT DEFAULT 1,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE resources (id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NOT NULL,name VARCHAR(255),is_active TINYINT DEFAULT 1,min_booking_slots INT DEFAULT NULL,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE pricing_windows (id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NOT NULL,resource_id INT DEFAULT NULL,day_of_week INT,time_from TIME,time_to TIME,price_per_slot DECIMAL(10,2),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE company_booking_settings (company_id INT PRIMARY KEY,min_advance_minutes INT DEFAULT 0,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE reservations (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,user_id INT NOT NULL,category_id INT NOT NULL,total_price DECIMAL(10,2) DEFAULT 0,status ENUM('pending','confirmed','rejected','cancelled') DEFAULT 'pending',booking_type ENUM('customer','internal') DEFAULT 'customer',label VARCHAR(255),recurrence_group CHAR(36),note TEXT,customer_first_name VARCHAR(100),customer_last_name VARCHAR(100),customer_email VARCHAR(255),customer_phone VARCHAR(50),cancel_token_hash CHAR(64),cancel_token_expires_at DATETIME,cancelled_by VARCHAR(20),cancelled_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE reservation_slots (id INT AUTO_INCREMENT PRIMARY KEY,reservation_id INT NOT NULL,resource_id INT NOT NULL,date DATE,time_start TIME,time_end TIME,price DECIMAL(10,2) DEFAULT 0,UNIQUE KEY unique_slot(resource_id,date,time_start),FOREIGN KEY(reservation_id) REFERENCES reservations(id) ON DELETE CASCADE,FOREIGN KEY(resource_id) REFERENCES resources(id) ON DELETE CASCADE);
